def stream_rows(resource, transform):
    failed = False
    try:
        try:
            while True:
                row = resource.read_next()
                if row is None:
                    break
                yield transform(row)
        except GeneratorExit:
            raise
        except BaseException:
            # An iteration or a transformation error: remember it so a
            # failing cleanup cannot mask the original error.
            failed = True
            raise
    finally:
        try:
            resource.close()
        except BaseException:
            if not failed:
                raise
            # Cleanup failed while an iteration or transform error was
            # already active: preserve the original error.
